, {"_id": 1779885139061.4075, "type": "zoom platform", "score": 5, "title": "Video Conferencing Tools Used for online teaching and hybrid classrooms.  Zoom", "quadrant": "Quadrant I: e-Tutorial, Tools to Report: Zoom, Google Meet, Microsoft Teams, or recorded screencasts", "description": "Online clasees taken from"}, {"_id": 1779885193877.3262, "type": "Mobile Phones VN app and video editor", "score": 5, "title": "ICT-Based Learning Through SDG Awareness Reel Making Activity", "quadrant": "Quadrant II: e-Content", "description": "ICT-based teaching materials were used to encourage students to create awareness reels using mobile phones under the Bharat Environment Program – A Bharat Sustainability Campus Mission 2026. Students developed creative digital content on SDGs, sustainability, and environmental awareness through interactive and technology-based learning methods."}, {"_id": 1779885214294.0054, "type": "Provded Youtube, Recorded Video links in every project Brief", "score": 5, "title": "Multimedia Tools Used to play videos, animations, and audio during teaching.  YouTube", "quadrant": "Quadrant I: Audio-video lectures", "description": "Multimedia tools were used to play videos, animations, and audio content during teaching sessions for better understanding and interactive learning. Subject-related YouTube links were shared regularly, and videos were presented in class to explain concepts through visual and audio-based learning methods."}, {"_id": 1779885256520.7607, "type": "Learning Management System JUNO ERP was used to upload class materials, subject briefs, presentations, notes, and academic resources regularly. The platform supported organized digital learning, easy student access to study materials, and continuous academic communication throughout the semester.", "score": 5, "title": "Learning Management Systems (LMS)", "quadrant": "Quadrant I: e-Tutorial", "description": "JUNO ERP"}, {"_id": 1779885263942.7366, "type": "Design & Creative Learning Through CorelDRAW Software", "score": 5, "title": "Design & Creative Tools  Especially useful for art, design, and creative students.", "quadrant": "Quadrant IV- Used CorelDRAW for practical learning of digital art and design skills.", "description": "CorelDRAW"}, {"_id": 1779986524922.9868, "type": "New technologies", "score": 5, "title": "FABLAB 3D printing", "quadrant": "Quadrant IV: Self-Assessment", "description": "Students used FABLAB facilities to learn new technologies, 3D printing processes, machine operations, and digital fabrication techniques through practical ICT-based learning and hands-on experience."}, {"_id": 1779987092127.3232, "type": "https://type.method.ac/", "score": 5, "title": "ICT Tools Used for BFA Applied Arts and Game Design Learning", "quadrant": "Quadrant IV: Self-Assessment, Learning form games", "description": "ICT tools were used for teaching typography and alignment concepts through interactive digital learning methods. Students learned spacing, kerning, and typography principles using the Kern Type Game website, making learning engaging through practical game-based activities and exercises."}, {"_id": 1779989971822.0928, "type": "Whatsapp and Mail", "score": 5, "title": "ICT-Based Academic Communication Through WhatsApp Groups and Email", "quadrant": "Quadrant III: Web Resources", "description": "ICT-Based Academic Communication Through WhatsApp Groups and Email"}, {"_id": 1780028283248.2295, "type": "Coursera", "score": 0, "title": "ICT-Based Learning Through Coursera Courses Aligned with Syllabus", "quadrant": "Quadrant-II (e-Content), Quadrant-III (Web Resources)", "description": "Under ICT-based learning, students used Coursera to complete online courses aligned with the syllabus, helping them gain practical knowledge, digital learning experience, and industry-relevant skills."}], "ipr": [{"_id": 1779794344880.424, "scope": "", "score": "", "title": "", "file_no": "", "ipr_date": "", "ipr_status": ""}], "fdps": [{"_id": 1779794344880